import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { LS_ACCESS_TOKEN } from '06_shared/constants/localStorage';
export const userApi = createApi({
    reducerPath: 'userApi',
    tagTypes: ['user', 'websocketToken'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        login: builder.mutation({
            query: (body) => ({
                url: '/auth/login',
                method: RequestMethods.POST,
                body,
            }),
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    const accessToken = `${data.result?.token_type} ${data.result?.access_token}`;
                    localStorage.setItem(LS_ACCESS_TOKEN, accessToken);
                    dispatch(userApi.endpoints.getMe.initiate());
                    dispatch(userApi.endpoints.getWebsocketToken.initiate());
                }
                catch (e) {
                    console.error('Error in queryFulfilled login', e);
                }
            },
        }),
        signup: builder.mutation({
            query: (body) => ({
                url: '/users',
                method: RequestMethods.POST,
                body,
            }),
        }),
        getMe: builder.query({
            query: () => ({
                url: '/auth/me',
                method: RequestMethods.GET,
            }),
            providesTags: ['user'],
        }),
        getWebsocketToken: builder.query({
            query: () => ({
                url: '/auth/websocket-token',
                method: RequestMethods.POST,
            }),
            providesTags: ['websocketToken'],
        }),
    }),
});
export const { useLoginMutation, useSignupMutation, useGetMeQuery, useGetWebsocketTokenQuery, } = userApi;
